def count_unique_even_numbers(digits):
    res = set()
    n = len(digits)
    # Try all ordered triplets (i, j, k) with i ≠ j ≠ k
    for i in range(n):
        # Hundreds place cannot be 0
        if digits[i] == 0:
            continue
        for j in range(n):
            if j == i:
                continue
            for k in range(n):
                if k == i or k == j:
                    continue
                # Units place must be even
                if digits[k] % 2 == 0:
                    num = digits[i] * 100 + digits[j] * 10 + digits[k]
                    res.add(num)
    return len(res)
